INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6616358, 986925, 101668, '<td valign="top">Het nie gestem die week nie, en nou is ek al weer jammer daaroor. Baie geluk Rian. Jy is besig om te diversifiseer. Die monument sal altyd spesiaal bly en jou fotos verewig dit vir die nageslag. so mooi!</td>', 'Het nie gestem die week nie, en nou is ek al weer jammer daaroor. Baie geluk Rian. Jy is besig om te diversifiseer. Die monument sal altyd spesiaal bly en jou fotos verewig dit vir die nageslag. so mooi!', '2011-12-12 00:15:22.000000', NULL, 0),
(6616362, 986701, 68504, '<td valign="top">I like the way you have utterly featured the hat.</td>', 'I like the way you have utterly featured the hat.', '2011-12-12 00:16:14.000000', NULL, 0),
(6616363, 986955, 54645, '<td valign="top">Bugger, what a crab. Well done.</td>', 'Bugger, what a crab. Well done.', '2011-12-12 00:18:25.000000', NULL, 0),
(6616368, 987072, 123833, '<td valign="top">Congrats on Top 10!</td>', 'Congrats on Top 10!', '2011-12-12 00:21:15.000000', NULL, 0),
(6616369, 987072, 101668, '<td valign="top">I did not get round to vote this week, this is lovely, congrats on the seventh place.</td>', 'I did not get round to vote this week, this is lovely, congrats on the seventh place.', '2011-12-12 00:21:41.000000', NULL, 0),
(6616377, 986718, 114285, '<td valign="top">Congrats Wendy, nice one.</td>', 'Congrats Wendy, nice one.', '2011-12-12 00:24:46.000000', NULL, 0),
(6616378, 987086, 101668, '<td valign="top">Would have given this a ten if I had voted. Lovely composition and deserves a higher place. Strong entries this week and you should be real proud of the 16th place but to my mind it should''ve scored higher. Real eyecatcher this one.</td>', 'Would have given this a ten if I had voted. Lovely composition and deserves a higher place. Strong entries this week and you should be real proud of the 16th place but to my mind it should''ve scored higher. Real eyecatcher this one.', '2011-12-12 00:24:47.000000', NULL, 0),
(6616380, 986693, 75713, '<td valign="top">Beautifully photographed Alice.</td>', 'Beautifully photographed Alice.', '2011-12-12 00:26:30.000000', NULL, 0),
(6616385, 986925, 17507, '<td valign="top">This really is a lovely shot--one of my highest votes. The placement of the sun is just perfect... I have trouble imagining that there''s a better time of day to shoot! But I''d happily be proven wrong :) Congrats on your blue!</td>', 'This really is a lovely shot--one of my highest votes. The placement of the sun is just perfect... I have trouble imagining that there''s a better time of day to shoot! But I''d happily be proven wrong :) Congrats on your blue!', '2011-12-12 00:30:29.000000', NULL, 0),
(6616387, 986008, 30982, '<td valign="top">Is that a satellite across the bottom?  Do you weight your tripod at all to keep it all perfectly still?  This kind of stuff amazes me!  And congrats on the ribbon, too.</td>', 'Is that a satellite across the bottom?  Do you weight your tripod at all to keep it all perfectly still?  This kind of stuff amazes me!  And congrats on the ribbon, too.', '2011-12-12 00:33:01.000000', NULL, 0),
(6616389, 986865, 30982, '<td valign="top">This really is magnificent.  Like a fairy tale.</td>', 'This really is magnificent.  Like a fairy tale.', '2011-12-12 00:35:24.000000', NULL, 0),
(6616390, 986008, 54446, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> Is that a satellite across the bottom?  Do you weight your tripod at all to keep it all perfectly still?  This kind of stuff amazes me!  And congrats on the ribbon, too. </i></td></tr></table> <br/>Airplane traversed the sky from Northwest to East.  Probably heading for Denver International, which is 80 miles away.  I watched the plane hit air turbulence... common over the front range of the Rockies.  My Gitzo tripod has a center pole with a convenient hook at the bottom.  I hang my camera bag on that hook to weigh down the tripod.  It was a night of periodic gusty winds.</td>', 'Originally posted by Melethia: Is that a satellite across the bottom?  Do you weight your tripod at all to keep it all perfectly still?  This kind of stuff amazes me!  And congrats on the ribbon, too.  Airplane traversed the sky from Northwest to East.  Probably heading for Denver International, which is 80 miles away.  I watched the plane hit air turbulence... common over the front range of the Rockies.  My Gitzo tripod has a center pole with a convenient hook at the bottom.  I hang my camera bag on that hook to weigh down the tripod.  It was a night of periodic gusty winds.', '2011-12-12 00:36:46.000000', NULL, 0),
(6616395, 987072, 113156, '<td valign="top">Well done Anita, great TT shot.</td>', 'Well done Anita, great TT shot.', '2011-12-12 00:38:57.000000', NULL, 0),
